<template><article class="metric-panel"><div><span>{{ metric.label }} <em v-if="isDemo" class="demo-label">演示数据</em></span><strong v-if="metric.status==='measured'">{{ metric.value }}<small>{{ metric.unit || '' }}</small></strong><strong v-else class="metric-status">{{ statusLabel }}</strong></div><p>{{ isDemo ? '演示数据，不进入正式趋势或临床决策' : sourceLabel }}</p><details v-if="metric.status==='measured'"><summary>查看来源与质量</summary><dl><div><dt>来源</dt><dd>{{ sourceLabel }}</dd></div><div v-if="metric.measured_at"><dt>时间</dt><dd>{{ formatDate(metric.measured_at) }}</dd></div><div v-if="metric.provider"><dt>Provider</dt><dd>{{ metric.provider }}</dd></div><div v-if="metric.algorithm"><dt>算法</dt><dd>{{ metric.algorithm }}</dd></div><div v-if="metric.instrument"><dt>量表</dt><dd>{{ metric.instrument }} {{ metric.version }}</dd></div></dl></details></article></template>
<script setup lang="ts">import { computed } from 'vue';import type { MetricV2 } from '@/api/v2';const props=defineProps<{metric:MetricV2}>();const isDemo=computed(()=>props.metric.quality?.source_status==='mock');const statusLabel=computed(()=>({not_observed:'本次未测得',not_administered:'本次未施测',invalid:'数据无效',insufficient:'数据不足',not_comparable:'不可比较',unsupported:'当前系统尚未支持'} as Record<string,string>)[props.metric.status]||props.metric.message||props.metric.status);const sourceLabel=computed(()=>({current_training_session:'本次训练实际测得',latest_formal_assessment:'最近一次正式评估',formal_assessment:'正式评估',unsupported:'未实现'} as Record<string,string>)[props.metric.display_source||'']||'训练事实');function formatDate(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))};</script>
